    Wv = C.get(f"model.layers.{l}.self_attn.v_proj.weight"); Wo = C.get(f"model.layers.{l}.self_attn.o_proj.weight")
    return (((En[ids]*gin) @ Wv.T) @ Wo[:, h*256:(h+1)*256].T) * gpost
